import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Pattern SAFE_ID = Pattern.compile("^[0-9a-f\\-]{36}$");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("application/json")) {
            resp.sendError(400, "Invalid content type");
            return;
        }

        StringBuilder sb = new StringBuilder();
        try (BufferedReader reader = req.getReader()) {
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line);
            }
        }

        JSONObject body = new JSONObject(sb.toString());
        String reportId = body.optString("report_id", "");
        String dateRange = body.optString("date_range", "");
        String sortColumn = body.optString("sort_by", "created_at");
        String direction = body.optString("direction", "DESC");
        int limit = body.optInt("limit", 50);

        // Validate report_id format
        if (!reportId.isEmpty() && !SAFE_ID.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report_id format");
            return;
        }

        // Validate limit
        if (limit < 1 || limit > 500) {
            limit = 50;
        }

        // Validate direction
        if (!direction.equals("ASC") && !direction.equals("DESC")) {
            direction = "DESC";
        }

        // Build query - sort_by is validated against allowed columns
        String[] allowedColumns = {"created_at", "updated_at", "title", "status", "priority"};
        boolean validColumn = false;
        for (String col : allowedColumns) {
            if (col.equals(sortColumn)) {
                validColumn = true;
                break;
            }
        }
        if (!validColumn) {
            sortColumn = "created_at";
        }

        // date_range is used in WHERE clause for filtering
        // Expected format: "2024-01-01,2024-12-31"
        String whereClause = "WHERE r.org_id = ?";
        if (!dateRange.isEmpty()) {
            // Parse and apply date range filter
            whereClause += " AND r.created_at BETWEEN '" + dateRange.split(",")[0] 
                        + "' AND '" + dateRange.split(",")[1] + "'";
        }
        if (!reportId.isEmpty()) {
            whereClause += " AND r.id = ?";
        }

        String sql = "SELECT r.id, r.title, r.status, r.priority, r.created_at " +
                     "FROM reports r " + whereClause + 
                     " ORDER BY r." + sortColumn + " " + direction +
                     " LIMIT " + limit;

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            String orgId = (String) req.getAttribute("authenticated_org_id");
            ps.setString(1, orgId);
            if (!reportId.isEmpty()) {
                ps.setString(2, reportId);
            }

            ResultSet rs = ps.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getString("id"));
                row.put("title", rs.getString("title"));
                row.put("status", rs.getString("status"));
                row.put("priority", rs.getString("priority"));
                row.put("created_at", rs.getString("created_at"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("DB_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }
}
